EXTRA_STYLE = r'''
.steps.four{grid-template-columns:repeat(4,1fr);margin-bottom:14px}.step[data-stage]{cursor:pointer;border:1px solid #dfe5ee;border-top:4px solid #ccd6e4;border-radius:10px}.step[data-stage]:hover{background:#f7faff}.step[data-stage].current{border-top-color:#2763dc;background:#f1f6ff}.stage-panel{display:none}.stage-panel.current{display:block}.source-grid,.asset-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.source,.asset-row{border:1px solid #dce3ed;border-radius:11px;padding:11px;background:#fff}.source img,.thumb img{width:100%;height:120px;object-fit:contain;background:#f5f7fa;border-radius:8px}.source .placeholder,.thumb .placeholder{height:120px;display:grid;place-items:center;background:#f5f7fa;border-radius:8px;color:#8492a6;font-size:12px}.asset-row{display:grid;grid-template-columns:72px minmax(140px,1.1fr) minmax(170px,1.5fr) minmax(160px,1fr);align-items:center;gap:12px}.element-mini{width:64px;height:54px;border-radius:8px;background:#f3f6fa;border:1px solid #e1e7ef;display:grid;place-items:center;overflow:hidden;position:relative}.element-mini img{width:100%;height:100%;object-fit:contain;cursor:zoom-in}.element-mini span{font-size:9px;color:#64748b;text-align:center;line-height:1.2;padding:3px}.element-mini .mini-state{position:absolute;left:2px;bottom:2px;background:rgba(255,255,255,.9);border-radius:3px;padding:1px 3px;font-size:8px}.asset-row.heading{font-size:12px;font-weight:800;background:#f6f8fb}.asset-row input[type=checkbox],.asset-row input[type=radio]{width:auto}.asset-title strong{display:block}.asset-title small{color:#64748b}.choice{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.choice label{margin:0;font-size:12px}.budget-table{width:100%;border-collapse:collapse}.budget-table th,.budget-table td{border-bottom:1px solid #e4e9f1;padding:11px;text-align:left}.budget-table th:last-child,.budget-table td:last-child{text-align:right}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.metric{border-radius:10px;padding:14px;background:#f6f8fb}.metric strong{display:block;font-size:22px;margin-top:5px}.gallery{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}.thumb{border:1px solid #dce3ed;border-radius:10px;padding:9px;cursor:pointer;background:#fff}.thumb:hover{border-color:#2763dc}.thumb strong{display:block;margin-top:7px;font-size:12px}.status-ok{color:#217a50;font-weight:800}.footer-nav{position:sticky;bottom:0;background:rgba(244,246,250,.96);backdrop-filter:blur(5px);padding:10px 0}.modal{position:fixed;inset:0;background:rgba(9,18,32,.72);display:none;place-items:center;z-index:50;padding:30px}.modal.open{display:grid}.modal-card{background:#fff;max-width:900px;width:100%;border-radius:14px;padding:16px}.modal-card img{width:100%;max-height:65vh;object-fit:contain;background:#f5f7fa}.tiny{font-size:11px;color:#64748b}.warning{color:#8a5b00}.rule-input{padding:8px}.disabled-note{opacity:.65}.result-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}@media(max-width:1100px){.source-grid,.asset-grid,.gallery{grid-template-columns:repeat(2,1fr)}.asset-row{grid-template-columns:72px 1fr}.asset-row.heading{display:none}.summary{grid-template-columns:1fr}}@media(max-width:650px){.steps.four,.source-grid,.asset-grid,.gallery{grid-template-columns:1fr}}
.source-class-label{display:block;margin-top:8px;font-size:11px;font-weight:800;color:#1f55b5}.source [data-source-class]{width:100%;margin:3px 0 7px;border:2px solid #8fb2ef;background:#f7faff}.element-source-select{width:100%;margin:0 0 7px}
'''


IMAGE_ASSET_V4 = r'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>이미지 요소 자산 생성기</title><style>''' + STYLE + EXTRA_STYLE + r'''</style></head><body><div class="shell">''' + SIDE + r'''<main class="main"><header class="top"><div><h1>이미지 요소 자산 생성기</h1><div class="muted">원본을 역할별 재사용 이미지 요소로 정리하고, 비용을 확인한 뒤 한 번에 승인합니다.</div></div>''' + AUTH + r'''</header>
<div class="steps four" id="assetSteps">
 <div class="step current" role="button" tabindex="0" data-stage="1"><strong>1 원본 확인</strong><small>상품정보 등록 원본</small></div>
 <div class="step" role="button" tabindex="0" data-stage="2"><strong>2 요소 설정</strong><small>이름·규칙·제작 방식</small></div>
 <div class="step" role="button" tabindex="0" data-stage="3"><strong>3 제작·예산</strong><small>선택 자동 반영</small></div>
 <div class="step" role="button" tabindex="0" data-stage="4"><strong>4 통합 검토·승인</strong><small>한 번만 최종 승인</small></div>
</div>

<section class="card stage-panel current" data-panel="1"><div class="head"><h2>1. 등록 원본 확인</h2><a class="btn soft" href="/product-registration">원본 추가 등록</a></div>
 <div class="three"><div><label>상품</label><select id="product"></select></div><div><label>기본 FACT</label><input id="factState" disabled></div><div><label>원본 이미지</label><input id="imageState" disabled></div></div>
 <div class="notice" style="margin-top:10px">여기서는 상품정보 등록에서 저장한 원본을 불러옵니다. 원본은 변경하지 않으며 촬영 분류와 이미지 요소 역할은 구분합니다.</div>
 <div id="sourceGallery" class="source-grid" style="margin-top:12px"><div class="empty">상품을 연결하면 원본이 표시됩니다.</div></div>
</section>

<section class="card stage-panel" data-panel="2"><div class="head"><h2>2. 이미지 요소 설정</h2><span class="badge">선택 항목과 추가 가능 항목 분리</span></div>
 <h3>이번 제작에 선택된 요소</h3><div id="elementRows"></div>
 <h3 style="margin-top:18px">추가 가능한 요소</h3><div id="availableElementRows"></div>
 <div class="notice" style="margin-top:10px">1단계 원본 선택과 실제로 연동됩니다. 원본이 부족하면 1단계에서 다시 선택하거나 상품정보 등록에서 원본을 추가합니다.</div>
</section>

<section class="card stage-panel" data-panel="3"><div class="head"><h2>3. 제작 계획과 예상비용</h2><span class="badge">2단계 선택 자동 반영</span></div>
 <div class="three"><div><label>보정 품질</label><select id="quality" onchange="recalculate()"><option value="economy">경제형 · 기본 정리</option><option value="standard" selected>표준형 · 온라인 판매</option><option value="premium">고급형 · 정밀 보정</option></select></div><div><label>출력 기준</label><select id="resolution" onchange="recalculate()"><option value="web" selected>온라인 표준</option><option value="high">온라인 고해상도</option><option value="print">인쇄용</option></select></div><div><label>예산 상한</label><input id="budgetCap" type="number" value="60000" min="0" step="1000" onchange="recalculate()"></div></div>
 <table class="budget-table" style="margin-top:12px"><thead><tr><th>비용 항목</th><th>산출 근거</th><th>예상비용</th></tr></thead><tbody id="budgetBody"></tbody></table>
 <div class="summary" style="margin-top:12px"><div class="metric">선택 요소<strong id="selectedCount">0개</strong></div><div class="metric">2차 조합<strong id="derivedCount">0개</strong></div><div class="metric">전체 예상비용<strong id="estimatedCost">0원</strong></div></div>
 <div id="budgetMessage" class="notice" style="margin-top:10px"></div><div class="actions" style="margin-top:10px"><a class="btn soft" href="/image-studio">보존된 기존 이미지 생성기 열기</a><button class="btn primary" type="button" onclick="markProductionReady()">통합 검토로 이동</button></div>
</section>

<section class="card stage-panel" data-panel="4"><div class="head"><h2>4. 통합 검토·승인</h2><span class="badge">1차·2차를 나누지 않고 한 번만 승인</span></div>
 <div id="reviewSummary" class="notice">3단계 제작 계획을 확인하면 검토 목록이 표시됩니다.</div><div id="resultGallery" class="gallery" style="margin-top:12px"></div>
 <div class="result-actions"><button class="btn soft" onclick="goStage(2)">요소 설정 수정</button><button class="btn soft" onclick="goStage(3)">예산 계획 수정</button><button class="btn primary" id="approveAssets" onclick="approveAll()">제작계획 최종 승인·실행</button></div><div id="approvalState" style="margin-top:10px"></div>
</section>

<div class="footer-nav"><div class="card" style="margin:0"><div class="actions" style="justify-content:space-between"><button class="btn soft" id="assetPrev">← 이전 단계</button><span class="muted" id="assetStageStatus">1 / 4</span><button class="btn primary" id="assetNext">다음 단계 →</button></div></div></div>
</main></div>
<div class="modal" id="previewModal" onclick="if(event.target===this)closePreview()"><div class="modal-card"><div class="head"><strong id="previewTitle">이미지 확대</strong><button class="btn" onclick="closePreview()">닫기</button></div><img id="previewImage" alt="선택 이미지 확대"><div class="tiny" id="previewMeta"></div></div></div>
<script>''' + COMMON_JS + r'''
const sourceLabels={RIGHT_45:'45도 우측 촬영',LEFT_45:'45도 좌측 촬영',FRONT:'정면 촬영',BACK:'후면 촬영',SIDE:'측면 촬영',LEFT:'측면 촬영',RIGHT:'측면 촬영',TOP:'상단 촬영',BOTTOM:'하단 촬영',DETAIL:'부분 상세 촬영',LIFESTYLE:'사용 모습 원본',COMPONENTS:'구성품',GROUP:'제품군·모음 촬영',INSTALLATION:'인포그래픽',UNASSIGNED:'미지정 원본'};
const sourceClassChoices=Object.entries(sourceLabels);
const elements=[
 {code:'MAIN',name:'대표 MAIN',rule:'제품 식별이 쉽고 작은 썸네일에서도 선명한 대표 구도',on:true,mode:'primary'},
 {code:'PRODUCT_FRONT',name:'제품 정면',rule:'정면·중앙·수직수평 유지',on:true,mode:'primary'},
 {code:'PRODUCT_BACK',name:'제품 후면',rule:'후면 라벨·구조가 정면과 혼동되지 않게 유지',on:false,mode:'primary'},
 {code:'PRODUCT_45',name:'제품 45도',rule:'우측 또는 좌측 45도·형태 보존',on:true,mode:'primary'},
 {code:'PRODUCT_SIDE',name:'제품 측면',rule:'측면 비례와 깊이 확인',on:true,mode:'primary'},
 {code:'PRODUCT_TOP',name:'제품 상단',rule:'상부 구조·개구부 확인',on:false,mode:'primary'},
 {code:'PRODUCT_BOTTOM',name:'제품 하단',rule:'하부 구조·배수·체결부 확인',on:false,mode:'primary'},
 {code:'LIFESTYLE',name:'사용 장면',rule:'실제 사용 맥락·상품 형태 보존',on:true,mode:'primary'},
 {code:'DETAIL',name:'부분 상세',rule:'재질·연결부·핵심 구조 확대',on:true,mode:'primary'},
 {code:'COMPONENTS',name:'구성품',rule:'누락 없이 정렬·수량 식별',on:true,mode:'primary'},
 {code:'GROUP',name:'제품군 모음사진',rule:'제품군 간 배율·간격·정렬·그림자 통일',on:false,mode:''},
 {code:'INFOGRAPHIC',name:'인포그래픽',rule:'정보·순서·관계를 시각적으로 설명',on:false,mode:'derived'},
 {code:'UNASSIGNED',name:'미지정',rule:'',on:false,mode:'primary'}
];
let sources=[],currentStage=1,planReady=false;
function storageKey(){return 'aiosImageAssetV4:'+(product?.value||'none')}
function savePlan(){if(!product?.value)return;localStorage.setItem(storageKey(),JSON.stringify({elements,quality:quality.value,resolution:resolution.value,budgetCap:budgetCap.value,planReady,updated_at:new Date().toISOString()}))}
function restorePlan(){const raw=localStorage.getItem(storageKey());if(!raw)return;try{const saved=JSON.parse(raw);for(const item of saved.elements||[]){const row=elements.find(x=>x.code===item.code);if(row)Object.assign(row,{on:!!item.on,mode:item.mode||'',rule:typeof item.rule==='string'?item.rule:row.rule})}if(saved.quality)quality.value=saved.quality;if(saved.resolution)resolution.value=saved.resolution;if(saved.budgetCap)budgetCap.value=saved.budgetCap;planReady=!!saved.planReady}catch{}}
function renderSources(){if(!sources.length){sourceGallery.innerHTML='<div class="empty">등록된 원본 이미지가 없습니다. 상품 기본정보 등록에서 원본을 추가해 주세요.</div>';return}sourceGallery.innerHTML=sources.map((x,i)=>{const url=x.fact_content_url||x.raw_content_url;const label=sourceLabels[x.slot_type]||sourceLabels.UNASSIGNED;return `<div class="source">${url?`<img src="${url}" alt="${label}" onclick="preview('${url}','${label}','${x.filename||''}')">`:'<div class="placeholder">이미지 처리 중</div>'}<strong>${label}</strong><div class="tiny">${x.filename||'파일명 없음'} · ${x.status||'등록'}</div></div>`}).join('')}
function modeCell(x){if(x.code==='GROUP')return `<div class="choice"><label><input type="radio" name="groupMode" value="primary" ${x.mode==='primary'?'checked':''}>1차 원본 보정</label><label><input type="radio" name="groupMode" value="derived" ${x.mode==='derived'?'checked':''}>2차 요소 조합</label></div>`;if(x.mode==='derived')return '<span class="badge">2차 자동</span>';return '<span class="badge">1차 자동</span>'}
function renderElements(){elementRows.innerHTML=elements.map((x,i)=>`<div class="asset-row"><input class="element-toggle" data-index="${i}" type="checkbox" ${x.on?'checked':''}><div class="asset-title"><strong>${x.name}</strong><small>${x.code}</small></div>${x.code==='UNASSIGNED'?`<input class="rule-input" data-rule="${i}" value="${esc(x.rule)}" placeholder="규칙·구도를 직접 입력">`:`<div class="tiny">${x.rule}</div>`}<div>${modeCell(x)}</div></div>`).join('');document.querySelectorAll('.element-toggle').forEach(el=>el.onchange=()=>{elements[+el.dataset.index].on=el.checked;planReady=false;savePlan();recalculate()});document.querySelectorAll('[data-rule]').forEach(el=>el.oninput=()=>{elements[+el.dataset.rule].rule=el.value;savePlan()});document.querySelectorAll('input[name=groupMode]').forEach(el=>el.onchange=()=>{const g=elements.find(x=>x.code==='GROUP');g.mode=el.value;g.on=true;renderElements();savePlan();recalculate()})}
function esc(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function costs(){const active=elements.filter(x=>x.on);const q={economy:.7,standard:1,premium:1.55}[quality.value]||1,r={web:1,high:1.25,print:1.7}[resolution.value]||1;const base=active.filter(x=>x.mode!=='derived').length*2800*q*r;const derived=active.filter(x=>x.mode==='derived').length*6500*q*r;const group=active.some(x=>x.code==='GROUP'&&x.mode==='derived')?4200*q*r:0;return {active,base:Math.round(base/100)*100,derived:Math.round(derived/100)*100,group:Math.round(group/100)*100,total:Math.round((base+derived+group)/100)*100}}
function recalculate(){const c=costs();budgetBody.innerHTML=`<tr><td>1차 요소 준비·보정</td><td>${c.active.filter(x=>x.mode!=='derived').length}개 × 품질·해상도</td><td>${c.base.toLocaleString()}원</td></tr><tr><td>2차 요소 제작</td><td>${c.active.filter(x=>x.mode==='derived').length}개</td><td>${c.derived.toLocaleString()}원</td></tr><tr><td>모음사진 조합 통일</td><td>배율·간격·정렬·배경·그림자</td><td>${c.group.toLocaleString()}원</td></tr>`;selectedCount.textContent=c.active.length+'개';derivedCount.textContent=c.active.filter(x=>x.mode==='derived').length+'개';estimatedCost.textContent=c.total.toLocaleString()+'원';const cap=+(budgetCap.value||0);budgetMessage.innerHTML=c.total>cap?`<strong class="warning">예산 상한보다 ${(c.total-cap).toLocaleString()}원 높습니다.</strong> 요소 또는 품질을 조정하세요.`:`예산 상한 이내입니다. 잔여 ${(cap-c.total).toLocaleString()}원.`;savePlan()}
function markProductionReady(){const g=elements.find(x=>x.code==='GROUP');if(g.on&&!g.mode)return alert('제품군 모음사진의 제작 구분을 선택해 주세요.');if(!elements.some(x=>x.on))return alert('제작할 이미지 요소를 하나 이상 선택해 주세요.');planReady=true;savePlan();renderReview();goStage(4)}
function sourceFor(code){const map={MAIN:['FRONT','RIGHT_45'],PRODUCT_FRONT:['FRONT'],PRODUCT_45:['RIGHT_45','LEFT_45'],PRODUCT_SIDE:['LEFT','RIGHT'],PRODUCT_TOP:['TOP'],PRODUCT_BOTTOM:['BOTTOM'],LIFESTYLE:['LIFESTYLE'],DETAIL:['DETAIL'],COMPONENTS:['COMPONENTS'],GROUP:['GROUP']};const types=map[code]||[];return sources.find(x=>types.includes(x.slot_type))||sources[0]}
function renderReview(){const c=costs(),active=c.active;reviewSummary.innerHTML=planReady?`<strong>${active.length}개 요소</strong> · 예상 ${c.total.toLocaleString()}원 · 1차와 2차 결과를 함께 검토합니다.`:'아직 제작 검토 계획이 확정되지 않았습니다.';resultGallery.innerHTML=active.map(x=>{const s=sourceFor(x.code),url=s&&(s.fact_content_url||s.raw_content_url);return `<div class="thumb" onclick="${url?`preview('${url}','${x.name}','${x.mode==='derived'?'2차 조합 계획':'1차 원본 기반'}')`:`alert('아직 연결된 원본 또는 제작 결과가 없습니다.')`}">${url?`<img src="${url}" alt="${x.name}">`:'<div class="placeholder">제작 결과 대기</div>'}<strong>${x.name}</strong><div class="tiny">${x.mode==='derived'?'2차 파생 요소':'1차 기본 요소'} · ${url?'원본 비교 가능':'결과 대기'}</div></div>`}).join('')||'<div class="empty">선택된 요소가 없습니다.</div>';const approved=localStorage.getItem('aiosImageAssetsApproved:'+product.value);approvalState.innerHTML=approved?'<span class="status-ok">이 상품의 이미지 요소 자산이 승인되어 상품마스터 보관함에 연결되었습니다.</span>':''}
function approveAll(){if(!planReady)return alert('먼저 3단계에서 제작 계획을 검토하세요.');if(!confirm('현재 상품의 이미지 요소 전체를 한 번에 승인하고 상품마스터 자산으로 저장하시겠습니까?'))return;const payload={product_id:product.value,elements:elements.filter(x=>x.on).map(x=>({code:x.code,name:x.name,mode:x.mode,rule:x.rule})),estimated_cost:costs().total,approved_at:new Date().toISOString()};localStorage.setItem('aiosImageAssetsApproved:'+product.value,JSON.stringify(payload));localStorage.setItem('aiosImageAssetsApproved',JSON.stringify(payload));approvalState.innerHTML='<span class="status-ok">통합 승인 완료 · 상품마스터 이미지 요소 자산 보관함에 연결되었습니다.</span>'}
function preview(url,title,meta){previewTitle.textContent=title;previewImage.src=url;previewMeta.textContent=meta||'';previewModal.classList.add('open')}function closePreview(){previewModal.classList.remove('open');previewImage.src=''}
function goStage(n){currentStage=Math.max(1,Math.min(4,n));document.querySelectorAll('[data-panel]').forEach(x=>x.classList.toggle('current',+x.dataset.panel===currentStage));document.querySelectorAll('#assetSteps .step').forEach(x=>x.classList.toggle('current',+x.dataset.stage===currentStage));assetPrev.disabled=currentStage===1;assetNext.disabled=currentStage===4;assetStageStatus.textContent=currentStage+' / 4';if(currentStage===3)recalculate();if(currentStage===4)renderReview();document.querySelector(`[data-panel="${currentStage}"]`).scrollIntoView({behavior:'smooth',block:'start'})}
function normalizeRegisteredSource(x){const raw=String(x.source_classification||'unknown').toLowerCase(),mapping={unknown:'UNASSIGNED',front:'FRONT',back:'BACK',right_45:'RIGHT_45',left_45:'LEFT_45',side:'SIDE',top:'TOP',bottom:'BOTTOM',detail:'DETAIL',usage_original:'LIFESTYLE',components:'COMPONENTS',group:'GROUP',installation:'INSTALLATION'},classification=mapping[raw]||'UNASSIGNED';return {id:x.id,slot_type:classification,status:'등록 원본',filename:x.filename||'',fact_content_url:`/api/v1/product-registration-assets/references/${x.id}/content?tenant_id=${tenant}`,source_store:'product-registration'}}
async function loadSources(){let factRows=[],registeredRows=[];try{const data=await api(`/api/v1/product-registration/products/${product.value}/images?tenant_id=${tenant}`);registeredRows=(data.assets||[]).map(normalizeRegisteredSource)}catch(e){}try{const data=await api(`/api/v1/product-image-facts/products/${product.value}?tenant_id=${tenant}`);factRows=data.images||[]}catch(e){}const seen=new Set();sources=[...registeredRows,...factRows].filter(x=>{const key=x.reference_asset_id||x.id||x.filename;if(seen.has(key))return false;seen.add(key);return true});imageState.value=sources.length?`${sources.length}장 등록`:'등록 원본 없음';renderSources()}
async function refresh(){const p=products.find(x=>x.id===product.value);if(!p)return;factState.value=p.master_ready?'확인 완료':'보완 필요: '+(p.master_missing_labels||[]).join(', ');restorePlan();renderElements();recalculate();await loadSources();renderReview()}
async function connect(){try{await baseConnect();product.onchange=async()=>{localStorage.setItem('aiosProduct',product.value);planReady=false;await refresh();goStage(1)};await refresh()}catch(e){alert(e.message)}}
document.querySelectorAll('#assetSteps .step').forEach(x=>{x.onclick=()=>goStage(+x.dataset.stage);x.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();goStage(+x.dataset.stage)}}});assetPrev.onclick=()=>goStage(currentStage-1);assetNext.onclick=()=>goStage(currentStage+1);renderElements();recalculate();goStage(1);if(token.value)connect();

// DEC-085: multiple source candidates, reversible production exclusion,
// source-aware element selection, server-side plan/execution persistence.
function sourceGroupKey(x){return x.slot_type||'UNASSIGNED'}
function ensureSourceChoices(){const groups={};sources.forEach(x=>(groups[sourceGroupKey(x)]??=[]).push(x));Object.values(groups).forEach(rows=>{if(!rows.some(x=>x.primary&&!x.excluded)&&rows.length)rows[0].primary=true;rows.forEach((x,i)=>{x.excluded=!!x.excluded;x.support=!!x.support&&!x.primary;x.candidateNo=i+1})})}
function sourceChoicePayload(){return sources.map(x=>({id:x.id,slot_type:x.slot_type,filename:x.filename,primary:!!x.primary,support:!!x.support,excluded:!!x.excluded,preview_url:x.fact_content_url||x.raw_content_url||''}))}
async function updateAssetSourceClass(row,value){const reverse={UNASSIGNED:'unknown',FRONT:'front',BACK:'back',RIGHT_45:'right_45',LEFT_45:'left_45',SIDE:'side',TOP:'top',BOTTOM:'bottom',DETAIL:'detail',LIFESTYLE:'usage_original',COMPONENTS:'components',GROUP:'group',INSTALLATION:'installation'};await api(`/api/v1/product-registration/products/${product.value}/images/${row.id}/classification?tenant_id=${tenant}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({source_classification:reverse[value]||'unknown'})});row.slot_type=value;row.primary=false;row.support=false;ensureSourceChoices();renderSources();renderElements();recalculate();savePlan()}
renderSources=function(){ensureSourceChoices();if(!sources.length){sourceGallery.innerHTML='<div class="empty">등록된 원본 이미지가 없습니다. 상품 기본정보 등록에서 원본을 추가해 주세요.</div>';return}const groups={};sources.forEach(x=>(groups[sourceGroupKey(x)]??=[]).push(x));sourceGallery.innerHTML=Object.entries(groups).map(([type,rows])=>rows.map(x=>{const url=x.fact_content_url||x.raw_content_url,label=sourceLabels[type]||sourceLabels.UNASSIGNED,no=String(x.candidateNo).padStart(2,'0'),radioGroup=type==='UNASSIGNED'?`${type}-${x.id}`:type;return `<div class="source ${x.excluded?'disabled-note':''}">${url?`<img src="${url}" alt="${label}" onclick="preview('${url}','${label}-${no}','${esc(x.filename)}')">`:'<div class="placeholder">이미지 처리 중</div>'}<label class="source-class-label">촬영 분류 변경·저장</label><select data-source-class="${x.id}">${sourceClassChoices.map(v=>`<option value="${v[0]}" ${v[0]===x.slot_type?'selected':''}>${v[1]}</option>`).join('')}</select><strong>${label}-${no}</strong><div class="tiny">${esc(x.filename||'파일명 없음')}</div><div class="choice"><label><input type="radio" name="primary-${radioGroup}" data-primary="${x.id}" ${x.primary&&!x.excluded?'checked':''} ${x.excluded?'disabled':''}>주 원본</label><label><input type="checkbox" data-support="${x.id}" ${x.support?'checked':''} ${x.primary||x.excluded?'disabled':''}>보조 참조</label></div><button class="btn soft" type="button" data-exclude="${x.id}">${x.excluded?'다시 포함':'이번 제작에서 제외'}</button></div>`}).join('')).join('');sourceGallery.querySelectorAll('[data-source-class]').forEach(el=>el.onchange=async()=>{const row=sources.find(x=>String(x.id)===el.dataset.sourceClass);el.disabled=true;try{await updateAssetSourceClass(row,el.value)}catch(e){alert(String(e));el.disabled=false}});sourceGallery.querySelectorAll('[data-primary]').forEach(el=>el.onchange=()=>{const chosen=sources.find(x=>String(x.id)===el.dataset.primary);if(chosen.slot_type!=='UNASSIGNED')sources.filter(x=>x.slot_type===chosen.slot_type).forEach(x=>{x.primary=x===chosen;x.support=x===chosen?false:x.support});else{chosen.primary=true;chosen.support=false}renderSources();renderElements();savePlan()});sourceGallery.querySelectorAll('[data-support]').forEach(el=>el.onchange=()=>{const row=sources.find(x=>String(x.id)===el.dataset.support),selected=sources.filter(x=>x.slot_type===row.slot_type&&x.support).length;if(el.checked&&selected>=2){el.checked=false;return alert('보조 참조는 같은 분류에서 최대 2장입니다.')}row.support=el.checked;savePlan()});sourceGallery.querySelectorAll('[data-exclude]').forEach(el=>el.onclick=()=>{const row=sources.find(x=>String(x.id)===el.dataset.exclude);row.excluded=!row.excluded;if(row.excluded){row.primary=false;row.support=false}ensureSourceChoices();renderSources();renderElements();recalculate();savePlan()})}
function sourceCandidatesFor(code){const map={MAIN:['FRONT','RIGHT_45','LEFT_45'],PRODUCT_FRONT:['FRONT'],PRODUCT_BACK:['BACK'],PRODUCT_45:['RIGHT_45','LEFT_45'],PRODUCT_SIDE:['SIDE','LEFT','RIGHT'],PRODUCT_TOP:['TOP'],PRODUCT_BOTTOM:['BOTTOM'],LIFESTYLE:['LIFESTYLE'],DETAIL:['DETAIL'],COMPONENTS:['COMPONENTS'],GROUP:['GROUP'],INFOGRAPHIC:['INSTALLATION']};const types=map[code]||[];return sources.filter(x=>types.includes(x.slot_type))}
function readiness(x){if(x.mode==='derived')return {ready:true,label:'2차 파생 제작',source:null};const explicit=x.source_id&&sources.find(s=>String(s.id)===String(x.source_id)&&!s.excluded);if(explicit)return {ready:true,label:'직접 연결 원본',source:explicit};const candidates=sourceCandidatesFor(x.code),usable=candidates.filter(s=>!s.excluded),primary=usable.find(s=>s.primary)||usable[0];if(primary)return {ready:true,label:'원본 준비됨',source:primary};if(candidates.length)return {ready:false,label:'선택 제외됨',action:'원본 다시 선택'};return {ready:false,label:'원본 없음',action:'원본 추가 등록'}}
function elementRow(x,i,selected){const r=readiness(x),preview=r.source&&(r.source.fact_content_url||r.source.raw_content_url),mini=preview?`<div class="element-mini"><img src="${preview}" alt="${x.name} 주 원본" onclick="preview('${preview}','${x.name}','${r.label}')"><span class="mini-state">${r.label}</span></div>`:`<div class="element-mini"><span>${x.mode==='derived'?'2차 제작':x.name}<br>원본 선택</span></div>`,sourceSelect=x.mode==='derived'?'':`<select class="element-source-select" data-element-source="${i}"><option value="">촬영 분류에 따라 자동 연결</option>${sources.filter(s=>!s.excluded).map(s=>`<option value="${s.id}" ${String(x.source_id||'')===String(s.id)?'selected':''}>${sourceLabels[s.slot_type]||'미지정'} · ${esc(s.filename)}</option>`).join('')}</select>`;return `<div class="asset-row">${mini}<div class="asset-title"><strong>${x.name}</strong><small>${x.code}${preview?' · 주 원본 연결':''}<br>${r.label}</small></div>${x.code==='UNASSIGNED'?`<input class="rule-input" data-rule="${i}" value="${esc(x.rule)}" placeholder="규칙·구도를 직접 입력">`:`<div class="tiny">${x.rule}</div>`}<div>${sourceSelect}${selected?`<button class="btn soft" data-remove-element="${i}">선택 해제</button>`:`<button class="btn primary" data-add-element="${i}">요소 추가</button>`}${!r.ready?` <button class="btn soft" data-fix-source="${r.action==='원본 다시 선택'?1:0}">${r.action}</button>`:''}</div></div>`}
renderElements=function(){ensureSourceChoices();elementRows.innerHTML=elements.map((x,i)=>x.on?elementRow(x,i,true):'').join('')||'<div class="empty">이번 제작에 선택된 요소가 없습니다.</div>';availableElementRows.innerHTML=elements.map((x,i)=>!x.on?elementRow(x,i,false):'').join('')||'<div class="empty">모든 요소가 선택되었습니다.</div>';document.querySelectorAll('[data-element-source]').forEach(el=>el.onchange=()=>{elements[+el.dataset.elementSource].source_id=el.value||null;planReady=false;renderElements();recalculate();savePlan()});document.querySelectorAll('[data-remove-element]').forEach(el=>el.onclick=()=>{elements[+el.dataset.removeElement].on=false;planReady=false;renderElements();recalculate();savePlan()});document.querySelectorAll('[data-add-element]').forEach(el=>el.onclick=()=>{const x=elements[+el.dataset.addElement];x.on=true;if(x.code==='GROUP'&&!x.mode)x.mode='derived';planReady=false;renderElements();recalculate();savePlan()});document.querySelectorAll('[data-fix-source]').forEach(el=>el.onclick=()=>el.dataset.fixSource==='1'?goStage(1):location.assign('/product-registration'));document.querySelectorAll('[data-rule]').forEach(el=>el.oninput=()=>{elements[+el.dataset.rule].rule=el.value;savePlan()})}
costs=function(){const active=elements.filter(x=>x.on),resolved=active.filter(x=>readiness(x).ready),q={economy:.7,standard:1,premium:1.55}[quality.value]||1,r={web:1,high:1.25,print:1.7}[resolution.value]||1,base=resolved.filter(x=>x.mode!=='derived').length*2800*q*r,derived=resolved.filter(x=>x.mode==='derived').length*6500*q*r,group=resolved.some(x=>x.code==='GROUP'&&x.mode==='derived')?4200*q*r:0;return {active,resolved,unresolved:active.filter(x=>!readiness(x).ready),base:Math.round(base/100)*100,derived:Math.round(derived/100)*100,group:Math.round(group/100)*100,total:Math.round((base+derived+group)/100)*100}}
function workflowPayload(){const c=costs();return {product_id:product.value,sources:sourceChoicePayload(),elements:elements.map(x=>{const r=readiness(x);return {code:x.code,name:x.name,mode:x.mode,rule:x.rule,selected:!!x.on,ready:r.ready,readiness:r.label,preview_url:r.source&&(r.source.fact_content_url||r.source.raw_content_url)||null}}),quality:quality.value,resolution:resolution.value,budget_cap:+budgetCap.value||0,estimated_cost:c.total}}
savePlan=function(){if(!product?.value)return;localStorage.setItem(storageKey(),JSON.stringify({elements,sources:sourceChoicePayload(),quality:quality.value,resolution:resolution.value,budgetCap:budgetCap.value,planReady,updated_at:new Date().toISOString()}));clearTimeout(window.assetPlanTimer);window.assetPlanTimer=setTimeout(()=>api(`/api/v1/image-asset-workflows/${product.value}?tenant_id=${tenant}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(workflowPayload())}).catch(()=>{}),250)}
restorePlan=function(){const raw=localStorage.getItem(storageKey());if(!raw)return;try{const saved=JSON.parse(raw);for(const item of saved.elements||[]){const row=elements.find(x=>x.code===item.code);if(row)Object.assign(row,{on:!!item.on,mode:item.mode||'',rule:typeof item.rule==='string'?item.rule:row.rule,source_id:item.source_id||null})}window.savedSourceChoices=saved.sources||[];if(saved.quality)quality.value=saved.quality;if(saved.resolution)resolution.value=saved.resolution;if(saved.budgetCap)budgetCap.value=saved.budgetCap;planReady=!!saved.planReady}catch{}}
const oldLoadSources=loadSources;loadSources=async function(){await oldLoadSources();for(const saved of window.savedSourceChoices||[]){const row=sources.find(x=>String(x.id)===String(saved.id));if(row)Object.assign(row,{primary:!!saved.primary,support:!!saved.support,excluded:!!saved.excluded})}ensureSourceChoices();renderSources();renderElements();recalculate()}
recalculate=function(){const c=costs(),q={economy:.7,standard:1,premium:1.55}[quality.value]||1,r={web:1,high:1.25,print:1.7}[resolution.value]||1;const identity=(x,state)=>{const url=state.source&&(state.source.fact_content_url||state.source.raw_content_url),thumb=url?`<div class="element-mini"><img src="${url}" alt="${x.name}"></div>`:`<div class="element-mini"><span>${state.ready?'2차 제작':'보완 필요'}</span></div>`;return `<div style="display:flex;align-items:center;gap:10px">${thumb}<div><strong>${x.name}</strong><div class="tiny">${x.code}</div></div></div>`};budgetBody.innerHTML=c.active.map(x=>{const state=readiness(x);if(!state.ready)return `<tr><td>${identity(x,state)}</td><td>${state.label} · 원본을 보완하거나 선택 해제</td><td>비용 제외</td></tr>`;let amount=(x.mode==='derived'?6500:2800)*q*r,basis=x.mode==='derived'?'2차 파생·조합 제작':'1차 주 원본 표준 보정';if(x.code==='GROUP'&&x.mode==='derived'){amount+=4200*q*r;basis+=' · 배율·간격·배경 통일'}amount=Math.round(amount/100)*100;const src=state.source?` · ${state.source.filename||sourceLabels[state.source.slot_type]||'주 원본'}`:'';return `<tr><td>${identity(x,state)}</td><td>${basis}${src}</td><td>${amount.toLocaleString()}원</td></tr>`}).join('')+`<tr><td><strong>전체 합계</strong></td><td>비용 반영 ${c.resolved.length}개 · 보완 필요 ${c.unresolved.length}개</td><td><strong>${c.total.toLocaleString()}원</strong></td></tr>`;selectedCount.textContent=c.active.length+'개';derivedCount.textContent=c.resolved.filter(x=>x.mode==='derived').length+'개';estimatedCost.textContent=c.total.toLocaleString()+'원';budgetMessage.textContent=`선택 ${c.active.length}개 중 비용 반영 ${c.resolved.length}개 · 미선택 ${elements.length-c.active.length}개`;savePlan()}
renderReview=function(){const c=costs();reviewSummary.innerHTML=planReady?`<strong>제작 승인 대상 ${c.resolved.length}개</strong> · 보완 대기 ${c.unresolved.length}개 · 예상 ${c.total.toLocaleString()}원`:'아직 제작 검토 계획이 확정되지 않았습니다.';const readyCards=c.resolved.map(x=>{const r=readiness(x),url=r.source&&(r.source.fact_content_url||r.source.raw_content_url);return `<div class="thumb">${url?`<img src="${url}" alt="${x.name}" onclick="preview('${url}','${x.name}','${r.label}')">`:'<div class="placeholder">2차 제작 결과 대기</div>'}<strong>${x.name}</strong><div class="tiny">${x.mode==='derived'?'2차 파생 제작':'1차 주 원본 보정'} · 비용 반영</div></div>`}).join('');const waitingCards=c.unresolved.map(x=>{const r=readiness(x),idx=elements.indexOf(x);return `<div class="thumb disabled-note"><div class="placeholder">${r.label}</div><strong>${x.name}</strong><div class="tiny">승인 대상 아님 · 비용 제외</div><div class="result-actions"><button class="btn soft" data-review-fix="${r.action==='원본 다시 선택'?1:0}">${r.action}</button><button class="btn soft" data-review-remove="${idx}">선택 해제</button></div></div>`}).join('');resultGallery.innerHTML=`<h3 style="grid-column:1/-1">제작 승인 대상</h3>${readyCards||'<div class="empty" style="grid-column:1/-1">승인 가능한 요소가 없습니다.</div>'}${c.unresolved.length?`<h3 style="grid-column:1/-1;margin-top:12px">보완 대기 · 승인 제외</h3>${waitingCards}`:''}`;resultGallery.querySelectorAll('[data-review-fix]').forEach(el=>el.onclick=()=>el.dataset.reviewFix==='1'?goStage(1):location.assign('/product-registration'));resultGallery.querySelectorAll('[data-review-remove]').forEach(el=>el.onclick=()=>{elements[+el.dataset.reviewRemove].on=false;planReady=false;renderElements();recalculate();renderReview()});approveAssets.disabled=!planReady||!!c.unresolved.length||!c.resolved.length;approvalState.innerHTML=c.unresolved.length?'<span class="warning">보완 대기 요소를 해결하거나 이번 제작에서 선택 해제해야 최종 승인할 수 있습니다.</span>':''}
approveAll=async function(){const c=costs();if(!planReady)return alert('먼저 3단계에서 제작 계획을 검토하세요.');if(c.unresolved.length)return alert('원본 보완이 필요한 요소를 해결하거나 선택 해제해 주세요.');if(!confirm('현재 계획을 잠그고 승인된 요소의 제작을 실행하시겠습니까?'))return;approveAssets.disabled=true;approvalState.textContent='제작계획을 저장하고 대기열에 등록 중...';try{const result=await api(`/api/v1/image-asset-workflows/${product.value}/execute?tenant_id=${tenant}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(workflowPayload())});const rows=result.execution?.results||[];resultGallery.innerHTML=rows.map(x=>`<div class="thumb">${x.preview_url?`<img src="${x.preview_url}" alt="${x.name}">`:'<div class="placeholder">결과 대기</div>'}<strong>${x.name}</strong><div class="tiny">${x.status} · ${x.message}</div></div>`).join('');approvalState.innerHTML='<span class="status-ok">통합 승인 완료 · 중복 방지 키와 함께 서버 제작계획에 저장되었습니다.</span>';approveAssets.textContent='승인·실행 등록 완료'}catch(e){approvalState.textContent=String(e);approveAssets.disabled=false}}
setTimeout(()=>{if(product?.value)refresh()},0);
</script></body></html>'''
